SELECT o.id, o.order_no, o.publisher_id, o.taker_id, o.title, o.game_id, o.system_id, o.server_id, o.manager_id, o.boosting_type, o.price, o.security_deposit, o.efficiency_deposit, o.status, o.created_at, o.updated_at, u.username AS publisherUsername, u.avatar AS publisherAvatar, t.username AS takerUsername, t.avatar AS takerAvatar, g.name AS gameName, s.name AS systemName, sv.name AS serverName FROM tb_jmz_orders o LEFT JOIN tb_jmz_user u ON o.publisher_id = u.user_id LEFT JOIN tb_jmz_user t ON o.taker_id = t.user_id LEFT JOIN tb_jmz_games g ON o.game_id = g.id LEFT JOIN tb_jmz_systems s ON o.system_id = s.id LEFT JOIN tb_jmz_game_servers sv ON o.server_id = sv.id
( o.title LIKE CONCAT('%', #{query.title}, '%') OR o.order_no LIKE CONCAT('%', #{query.title}, '%') OR u.username LIKE CONCAT('%', #{query.title}, '%') OR t.username LIKE CONCAT('%', #{query.title}, '%') )
AND o.game_id = #{query.gameId}
AND o.system_id = #{query.systemId}
AND o.server_id = #{query.serverId}
AND o.manager_id = #{query.managerId}
AND o.status = #{query.status}
AND o.boosting_type = #{query.type}
AND o.price >= #{query.priceMin}
AND o.price <= #{query.priceMax}
AND o.publisher_id = #{query.publisherId}
AND o.taker_id = #{query.takerId}
ORDER BY o.price DESC
ORDER BY o.price ASC
ORDER BY o.security_deposit ASC
ORDER BY o.security_deposit DESC
ORDER BY o.efficiency_deposit ASC
ORDER BY o.efficiency_deposit DESC
ORDER BY o.created_at DESC
LIMIT #{offset}, #{pageSize}

SELECT COUNT(*)
FROM tb_jmz_orders o
LEFT JOIN tb_jmz_user u ON o.publisher_id = u.user_id


        (
            o.title LIKE CONCAT('%', #{query.title}, '%')
            OR o.order_no LIKE CONCAT('%', #{query.title}, '%')
            OR u.username LIKE CONCAT('%', #{query.title}, '%')
        )


        AND o.game_id = #{query.gameId}


        AND o.system_id = #{query.systemId}


        AND o.server_id = #{query.serverId}


        AND o.manager_id = #{query.managerId}


        AND o.status = #{query.status}


        AND o.boosting_type = #{query.type}


        AND o.price >= #{query.priceMin}


        AND o.price <= #{query.priceMax}


        AND o.publisher_id = #{query.publisherId}


        AND o.taker_id = #{query.takerId}

SELECT COUNT(*) FROM tb_jmz_orders
WHERE publisher_id = #{publisherId}
  AND created_at >= DATE_SUB(NOW(), INTERVAL 30 DAY)

SELECT o.id, o.order_no, o.title, o.status, o.created_at, o.game_id, o.system_id, o.server_id, o.boosting_type, o.description, o.account_info, o.time_limit, o.price, o.security_deposit, o.efficiency_deposit, o.publisher_id, u.username AS publisherUsername, u.avatar AS publisherAvatar, g.name AS gameName, g.icon AS gameIcon, s.name AS systemName, s.icon AS systemIcon, sv.name AS serverName, o.start_at, o.actual_at,
(SELECT COUNT(*) FROM tb_jmz_orders WHERE publisher_id = o.publisher_id AND created_at >= DATE_SUB(NOW(), INTERVAL 30 DAY)) AS publisherOrderCount30d,
(SELECT COALESCE( ROUND( COUNT(CASE WHEN status IN (8, 9, 10) THEN 1 END) * 1.0 / COUNT(*), 2 ), 0.00 ) FROM tb_jmz_orders WHERE publisher_id = o.publisher_id AND created_at >= DATE_SUB(NOW(), INTERVAL 30 DAY) AND status IN (5, 6, 8, 9, 10, 11)) AS publisherManagerRate30d FROM tb_jmz_orders o LEFT JOIN tb_jmz_user u ON o.publisher_id = u.user_id LEFT JOIN tb_jmz_games g ON o.game_id = g.id LEFT JOIN tb_jmz_systems s ON o.system_id = s.id LEFT JOIN tb_jmz_game_servers sv ON o.server_id = sv.id WHERE o.id = #{orderId}
